                        "poster":  "svLkVHmyTFcU57MgkDstnMajDYT.jpg",
                        "overview":  "The Incredible Hulk is an animated television series based on the Marvel Comics character of the same name. The series ran for 13 episodes on NBC in 1982, part of a combined hour with Spider-Man and His Amazing Friends. Unlike the previous live-action The Incredible Hulk television series from Universal in the 1970s, this series was based upon the Hulk comic-books and was able to portray the more fantastical elements of the comics as sticking to his true name and origin as well as featuring the return of the original characters in his life all of which the live-action series refused to show. It featured stories faithful to the source material from Marvel, In addition, new recurring characters were created for the series including the Hispanic family of father Rio and his youthful daughter Rita.",
